{"status":"proposed","agent":"implementer","role":"author","executor":"claude-code","summary":"Phase 2 (tasks 11-20): the notes repository and ten backend feature modules, all new files. I did not run typecheck, lint or build, and nothing was tested against a database.

Router and response conventions for phase 3 (`index.ts` and `api.ts`):
- Every router uses full paths relative to `/api` (for example `/notes`, `/trash/:id/restore`), so each is mounted with `app.use('/api', router)`.
- Exported routers are `notesRouter`, `foldersRouter`, `tagsRouter`, `searchRouter`, `trashRouter`, `checklistsRouter`, `attachmentsRouter` and `versionsRouter`.
- List endpoints are wrapped: `{ notes, activeCount }`, `{ folders }`, `{ tags }`, `{ results }`, `{ items, summary }`, `{ attachments }` and `{ versions }`.
- Single-resource endpoints return the bare object.
- Trash restore returns `{ note, restoredTo, folderName }`.
- Attachment upload uses the multipart field name `file`.

Behaviours you might not expect:
- `updateNote` syncs `checklist_items` by position instead of delete-and-reinsert, so item ids stay stable across saves. This is exported as `syncChecklistItems` and also used by the version restore.
- Archive and unarchive are idempotent. A repeat call returns the note without recording another event.
- A checklist PATCH also bumps the note's `updated_at`.
- `notes/repository.ts` also exports the request-parsing helpers `queryString`, `bodyRecord` and `parseDateParam`, which the other routes reuse.","proposedPatches":[{"baseCommit":"cc839ba8c3b95ef2c0866b23fab4421f8b87b414","files":[{"path":"backend/src/features/notes/repository.ts","action":"add","content":"import type { PoolClient } from 'pg';
import { query, withTransaction } from '../../lib/db.js';
import { badRequest, notFound } from '../../lib/errors.js';
import { recordActivity } from '../activity/repository.js';
import type { ActivityEvent } from '../activity/repository.js';
import { extractChecklistItems, htmlToPlainText } from '../export/markdown.js';

export interface NoteTag {
  id: string;
  name: string;
  color: string;
}

export interface SummaryRow {
  id: string;
  title: string;
  preview: string;
  folder_id: string | null;
  folder_name: string | null;
  tags: NoteTag[];
  pinned: boolean;
  is_archived: boolean;
  created_at: Date;
  updated_at: Date;
  checklist_total: number;
  checklist_done: number;
  has_attachments: boolean;
}

export interface NoteSummary {
  id: string;
  title: string;
  preview: string;
  folderId: string | null;
  folderName: string | null;
  tags: NoteTag[];
  pinned: boolean;
  archived: boolean;
  createdAt: Date;
  updatedAt: Date;
  checklistTotal: number;
  checklistDone: number;
  hasAttachments: boolean;
}

export interface NoteDetail extends NoteSummary {
  body: string;
}

export interface NoteFilters {
  folderId?: string;
  tagId?: string;
  pinned?: boolean;
  state?: 'active' | 'archived';
  tasks?: 'open' | 'complete';
  dateField?: 'updated' | 'created';
  from?: string;
  to?: string;
  hasAttachments?: boolean;
  sort?: 'updated' | 'created' | 'title' | 'pinned';
  limit?: number;
}

// Columns shared by every note summary query. The query must alias notes as n and
// include FOLDER_JOIN.
export const SUMMARY_COLUMNS = `
  n.id,
  n.title,
  left(regexp_replace(n.body_text, '\\s+', ' ', 'g'), 160) AS preview,
  n.folder_id,
  f.name AS folder_name,
  COALESCE((
    SELECT json_agg(json_build_object('id', t.id, 'name', t.name, 'color', t.color) ORDER BY lower(t.name), t.id)
      FROM note_tags nt
      JOIN tags t ON t.id = nt.tag_id AND t.user_id = n.user_id
     WHERE nt.note_id = n.id AND nt.user_id = n.user_id
  ), '[]'::json) AS tags,
  n.pinned,
  n.is_archived,
  n.created_at,
  n.updated_at,
  (SELECT count(*)::int FROM checklist_items c WHERE c.note_id = n.id AND c.user_id = n.user_id) AS checklist_total,
  (SELECT count(*)::int FROM checklist_items c WHERE c.note_id = n.id AND c.user_id = n.user_id AND c.checked) AS checklist_done,
  EXISTS (SELECT 1 FROM attachments a WHERE a.note_id = n.id AND a.user_id = n.user_id) AS has_attachments
`;

export const FOLDER_JOIN = 'LEFT JOIN folders f ON f.id = n.folder_id AND f.user_id = n.user_id';

// Trashed notes never appear in a normal view.
const BASE_PREDICATE = 'n.trashed_at IS NULL';

export function mapSummary(row: SummaryRow): NoteSummary {
  return {
    id: row.id,
    title: row.title,
    preview: row.preview,
    folderId: row.folder_id,
    folderName: row.folder_name,
    tags: row.tags,
    pinned: row.pinned,
    archived: row.is_archived,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    checklistTotal: row.checklist_total,
    checklistDone: row.checklist_done,
    hasAttachments: row.has_attachments,
  };
}

// ---------------------------------------------------------------------------
// Request parsing helpers shared by the feature routes
// ---------------------------------------------------------------------------

export function queryString(value: unknown): string | undefined {
  if (value === undefined) {
    return undefined;
  }
  if (typeof value !== 'string') {
    throw badRequest('Invalid query parameter.');
  }
  return value;
}

export function bodyRecord(body: unknown): Record<string, unknown> {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    throw badRequest('Invalid request body.');
  }
  return body as Record<string, unknown>;
}

export function parseDateParam(value: string): string {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value) || Number.isNaN(Date.parse(value))) {
    throw badRequest('Dates must use the format YYYY-MM-DD.');
  }
  return value;
}

function envPositive(name: string, fallback: number): number {
  const value = Number(process.env[name]);
  return Number.isFinite(value) && value > 0 ? value : fallback;
}

// ---------------------------------------------------------------------------
// Listing
// ---------------------------------------------------------------------------

const SORT_SQL: Record<NonNullable<NoteFilters['sort']>, string> = {
  updated: 'n.updated_at DESC, n.id',
  created: 'n.created_at DESC, n.id',
  title:
    "lower(CASE WHEN btrim(n.title) = '' THEN 'Untitled note' ELSE n.title END) ASC, n.updated_at DESC, n.id",
  pinned: 'n.pinned DESC, n.updated_at DESC, n.id',
};

export async function listNotes(
  userId: string,
  filters: NoteFilters = {}
): Promise<{ notes: NoteSummary[]; activeCount: number }> {
  const params: unknown[] = [userId];
  const add = (value: unknown): string => {
    params.push(value);
    return `$${params.length}`;
  };

  const where = ['n.user_id = $1', BASE_PREDICATE];

  if (filters.pinned) {
    where.push('n.pinned = true', 'n.is_archived = false');
  } else if (filters.state === 'archived') {
    where.push('n.is_archived = true');
  } else {
    where.push('n.is_archived = false');
  }

  if (filters.folderId) {
    where.push(`n.folder_id = ${add(filters.folderId)}`);
  }
  if (filters.tagId) {
    where.push(
      `EXISTS (SELECT 1 FROM note_tags nt WHERE nt.note_id = n.id AND nt.user_id = n.user_id AND nt.tag_id = ${add(
        filters.tagId
      )})`
    );
  }

  const unchecked =
    'EXISTS (SELECT 1 FROM checklist_items c WHERE c.note_id = n.id AND c.user_id = n.user_id AND c.checked = false)';
  const anyItem = 'EXISTS (SELECT 1 FROM checklist_items c WHERE c.note_id = n.id AND c.user_id = n.user_id)';
  if (filters.tasks === 'open') {
    where.push(unchecked);
  } else if (filters.tasks === 'complete') {
    where.push(anyItem, `NOT ${unchecked}`);
  }

  const dateColumn = filters.dateField === 'created' ? 'n.created_at' : 'n.updated_at';
  if (filters.from) {
    where.push(`${dateColumn} >= ${add(filters.from)}::date`);
  }
  if (filters.to) {
    where.push(`${dateColumn} < (${add(filters.to)}::date + 1)`);
  }

  if (filters.hasAttachments) {
    where.push('EXISTS (SELECT 1 FROM attachments a WHERE a.note_id = n.id AND a.user_id = n.user_id)');
  }

  const order = SORT_SQL[filters.sort ?? 'updated'];
  const limit = add(filters.limit ?? 500);

  const [list, count] = await Promise.all([
    query<SummaryRow>(
      `SELECT ${SUMMARY_COLUMNS}
         FROM notes n
         ${FOLDER_JOIN}
        WHERE ${where.join(' AND ')}
        ORDER BY ${order}
        LIMIT ${limit}`,
      params
    ),
    query<{ count: number }>(
      `SELECT count(*)::int AS count
         FROM notes n
        WHERE n.user_id = $1 AND ${BASE_PREDICATE} AND n.is_archived = false`,
      [userId]
    ),
  ]);

  return { notes: list.rows.map(mapSummary), activeCount: count.rows[0].count };
}

export async function getNote(userId: string, noteId: string): Promise<NoteDetail | null> {
  const result = await query<SummaryRow & { body: string }>(
    `SELECT ${SUMMARY_COLUMNS}, n.body
       FROM notes n
       ${FOLDER_JOIN}
      WHERE n.id = $1 AND n.user_id = $2 AND ${BASE_PREDICATE}`,
    [noteId, userId]
  );
  const row = result.rows[0];
  return row ? { ...mapSummary(row), body: row.body } : null;
}

// ---------------------------------------------------------------------------
// Creation and simple state changes
// ---------------------------------------------------------------------------

async function assertOwnedFolder(client: PoolClient, userId: string, folderId: string): Promise<void> {
  const result = await client.query('SELECT 1 FROM folders WHERE id = $1 AND user_id = $2', [folderId, userId]);
  if (result.rowCount === 0) {
    throw notFound();
  }
}

export async function createNote(userId: string, options: { folderId?: string | null } = {}): Promise<NoteDetail> {
  const id = await withTransaction(async (client) => {
    if (options.folderId) {
      await assertOwnedFolder(client, userId, options.folderId);
    }
    const inserted = await client.query<{ id: string }>(
      'INSERT INTO notes (user_id, folder_id) VALUES ($1, $2) RETURNING id',
      [userId, options.folderId ?? null]
    );
    const noteId = inserted.rows[0].id;
    await recordActivity(client, { userId, noteId, event: 'created' });
    return noteId;
  });
  const note = await getNote(userId, id);
  if (!note) {
    throw notFound();
  }
  return note;
}

export async function setPinned(userId: string, noteId: string, pinned: boolean): Promise<boolean> {
  const result = await query(
    'UPDATE notes SET pinned = $3 WHERE id = $1 AND user_id = $2 AND trashed_at IS NULL',
    [noteId, userId, pinned]
  );
  return (result.rowCount ?? 0) > 0;
}

export async function setFolder(userId: string, noteId: string, folderId: string | null): Promise<boolean> {
  return withTransaction(async (client) => {
    if (folderId) {
      await assertOwnedFolder(client, userId, folderId);
    }
    const result = await client.query(
      'UPDATE notes SET folder_id = $3 WHERE id = $1 AND user_id = $2 AND trashed_at IS NULL',
      [noteId, userId, folderId]
    );
    return (result.rowCount ?? 0) > 0;
  });
}

// Applies a state change and records its event. Repeating a change that is already in
// effect succeeds without recording a second event. Returns false for a missing note.
async function applyState(
  userId: string,
  noteId: string,
  assignments: string,
  guard: string,
  event: ActivityEvent
): Promise<boolean> {
  return withTransaction(async (client) => {
    const changed = await client.query(
      `UPDATE notes SET ${assignments}
        WHERE id = $1 AND user_id = $2 AND trashed_at IS NULL AND ${guard}`,
      [noteId, userId]
    );
    if ((changed.rowCount ?? 0) > 0) {
      await recordActivity(client, { userId, noteId, event });
      return true;
    }
    const exists = await client.query('SELECT 1 FROM notes WHERE id = $1 AND user_id = $2 AND trashed_at IS NULL', [
      noteId,
      userId,
    ]);
    return (exists.rowCount ?? 0) > 0;
  });
}

export function archive(userId: string, noteId: string): Promise<boolean> {
  return applyState(userId, noteId, 'is_archived = true, archived_at = now()', 'is_archived = false', 'archived');
}

export function unarchive(userId: string, noteId: string): Promise<boolean> {
  return applyState(userId, noteId, 'is_archived = false, archived_at = NULL', 'is_archived = true', 'unarchived');
}

export async function trash(userId: string, noteId: string): Promise<boolean> {
  return withTransaction(async (client) => {
    const changed = await client.query(
      'UPDATE notes SET trashed_at = now() WHERE id = $1 AND user_id = $2 AND trashed_at IS NULL',
      [noteId, userId]
    );
    if ((changed.rowCount ?? 0) === 0) {
      return false;
    }
    await recordActivity(client, { userId, noteId, event: 'trashed' });
    return true;
  });
}

export async function setNoteTags(userId: string, noteId: string, tagIds: string[]): Promise<boolean> {
  const unique = Array.from(new Set(tagIds));
  return withTransaction(async (client) => {
    const note = await client.query(
      'SELECT 1 FROM notes WHERE id = $1 AND user_id = $2 AND trashed_at IS NULL FOR UPDATE',
      [noteId, userId]
    );
    if (note.rowCount === 0) {
      return false;
    }
    if (unique.length > 0) {
      const owned = await client.query<{ count: number }>(
        'SELECT count(*)::int AS count FROM tags WHERE user_id = $1 AND id = ANY($2::uuid[])',
        [userId, unique]
      );
      if (owned.rows[0].count !== unique.length) {
        throw notFound();
      }
    }
    await client.query('DELETE FROM note_tags WHERE note_id = $1 AND user_id = $2', [noteId, userId]);
    if (unique.length > 0) {
      await client.query(
        'INSERT INTO note_tags (note_id, tag_id, user_id) SELECT $1, t.tag_id, $2 FROM unnest($3::uuid[]) AS t(tag_id)',
        [noteId, userId, unique]
      );
    }
    return true;
  });
}

// ---------------------------------------------------------------------------
// Checklist sync
// ---------------------------------------------------------------------------

// Mirrors the task items found in the note body into checklist_items, matching rows by
// position so item ids stay stable across saves.
export async function syncChecklistItems(
  client: PoolClient,
  userId: string,
  noteId: string,
  html: string
): Promise<void> {
  const items = extractChecklistItems(html);
  await client.query('DELETE FROM checklist_items WHERE note_id = $1 AND user_id = $2 AND position >= $3', [
    noteId,
    userId,
    items.length,
  ]);
  if (items.length === 0) {
    return;
  }
  const texts = items.map((item) => item.text);
  const checks = items.map((item) => item.checked);
  const positions = items.map((item) => item.position);
  await client.query(
    `UPDATE checklist_items c
        SET text = v.txt, checked = v.chk
       FROM unnest($3::text[], $4::boolean[], $5::int[]) AS v(txt, chk, pos)
      WHERE c.note_id = $1 AND c.user_id = $2 AND c.position = v.pos`,
    [noteId, userId, texts, checks, positions]
  );
  await client.query(
    `INSERT INTO checklist_items (note_id, user_id, text, checked, position)
     SELECT $1, $2, v.txt, v.chk, v.pos
       FROM unnest($3::text[], $4::boolean[], $5::int[]) AS v(txt, chk, pos)
      WHERE NOT EXISTS (
        SELECT 1 FROM checklist_items c WHERE c.note_id = $1 AND c.user_id = $2 AND c.position = v.pos
      )`,
    [noteId, userId, texts, checks, positions]
  );
}

// ---------------------------------------------------------------------------
// Content updates with versioning
// ---------------------------------------------------------------------------

async function snapshotPriorVersion(
  client: PoolClient,
  userId: string,
  noteId: string,
  prior: { title: string; body: string; body_text: string }
): Promise<void> {
  // OD-004: an empty prior state is never saved.
  if (prior.title.trim() === '' && prior.body_text.trim() === '') {
    return;
  }
  const intervalSeconds = envPositive('VERSION_INTERVAL_MINUTES', 5) * 60;
  const latest = await client.query<{ recent: boolean }>(
    `SELECT created_at > now() - make_interval(secs => $3) AS recent
       FROM note_versions
      WHERE note_id = $1 AND user_id = $2
      ORDER BY created_at DESC, id DESC
      LIMIT 1`,
    [noteId, userId, intervalSeconds]
  );
  if (latest.rows[0]?.recent) {
    return;
  }
  await client.query(
    `INSERT INTO note_versions (note_id, user_id, title, body, body_text, reason)
     VALUES ($1, $2, $3, $4, $5, 'autosave')`,
    [noteId, userId, prior.title, prior.body, prior.body_text]
  );
  // OD-005: keep the newest VERSION_RETENTION_COUNT versions.
  const keep = Math.max(1, Math.floor(envPositive('VERSION_RETENTION_COUNT', 100)));
  await client.query(
    `DELETE FROM note_versions
      WHERE note_id = $1 AND user_id = $2
        AND id NOT IN (
          SELECT id FROM note_versions
           WHERE note_id = $1 AND user_id = $2
           ORDER BY created_at DESC, id DESC
           LIMIT $3
        )`,
    [noteId, userId, keep]
  );
}

// Returns false when the note does not exist, is not owned, or is trashed.
export async function updateNote(
  userId: string,
  noteId: string,
  changes: { title?: string; body?: string }
): Promise<boolean> {
  return withTransaction(async (client) => {
    const current = await client.query<{ title: string; body: string; body_text: string }>(
      `SELECT title, body, body_text FROM notes
        WHERE id = $1 AND user_id = $2 AND trashed_at IS NULL
        FOR UPDATE`,
      [noteId, userId]
    );
    const row = current.rows[0];
    if (!row) {
      return false;
    }
    const title = changes.title ?? row.title;
    const body = changes.body ?? row.body;
    if (title === row.title && body === row.body) {
      return true;
    }

    await snapshotPriorVersion(client, userId, noteId, row);

    await client.query(
      `UPDATE notes
          SET title = $3, body = $4, body_text = $5, updated_at = now()
        WHERE id = $1 AND user_id = $2`,
      [noteId, userId, title, body, htmlToPlainText(body)]
    );
    await syncChecklistItems(client, userId, noteId, body);
    await recordActivity(client, { userId, noteId, event: 'updated' });
    return true;
  });
}
"},{"path":"backend/src/features/notes/routes.ts","action":"add","content":"import { Router } from 'express';
import { userIdOf } from '../../lib/requireAuth.js';
import { asyncHandler, badRequest, notFound, requireUuid } from '../../lib/errors.js';
import {
  archive,
  bodyRecord,
  createNote,
  getNote,
  listNotes,
  parseDateParam,
  queryString,
  setFolder,
  setNoteTags,
  setPinned,
  trash,
  unarchive,
  updateNote,
} from './repository.js';
import type { NoteFilters } from './repository.js';

// Paths are relative to /api.
export const notesRouter = Router();

const STATES = ['active', 'archived'] as const;
const TASKS = ['open', 'complete'] as const;
const DATE_FIELDS = ['updated', 'created'] as const;
const SORTS = ['updated', 'created', 'title', 'pinned'] as const;

function oneOf<T extends string>(value: string | undefined, allowed: readonly T[]): T | undefined {
  if (value === undefined || value === '') {
    return undefined;
  }
  const match = allowed.find((candidate) => candidate === value);
  if (!match) {
    throw badRequest('Invalid query parameter.');
  }
  return match;
}

function parseFilters(rawQuery: Record<string, unknown>): NoteFilters {
  const folderId = queryString(rawQuery.folderId);
  const tagId = queryString(rawQuery.tagId);
  const from = queryString(rawQuery.from);
  const to = queryString(rawQuery.to);
  const limitText = queryString(rawQuery.limit);

  const filters: NoteFilters = {
    pinned: queryString(rawQuery.pinned) === 'true',
    hasAttachments: queryString(rawQuery.hasAttachments) === 'true',
    state: oneOf(queryString(rawQuery.state), STATES),
    tasks: oneOf(queryString(rawQuery.tasks), TASKS),
    dateField: oneOf(queryString(rawQuery.dateField), DATE_FIELDS),
    sort: oneOf(queryString(rawQuery.sort), SORTS),
  };
  if (folderId) {
    filters.folderId = requireUuid(folderId);
  }
  if (tagId) {
    filters.tagId = requireUuid(tagId);
  }
  if (from) {
    filters.from = parseDateParam(from);
  }
  if (to) {
    filters.to = parseDateParam(to);
  }
  if (limitText) {
    const limit = Number(limitText);
    if (!Number.isInteger(limit) || limit < 1 || limit > 1000) {
      throw badRequest('Invalid query parameter.');
    }
    filters.limit = limit;
  }
  return filters;
}

notesRouter.get(
  '/notes',
  asyncHandler(async (req, res) => {
    const result = await listNotes(userIdOf(res), parseFilters(req.query));
    res.json(result);
  })
);

notesRouter.post(
  '/notes',
  asyncHandler(async (req, res) => {
    const body = bodyRecord(req.body ?? {});
    let folderId: string | null = null;
    if (body.folderId !== undefined && body.folderId !== null) {
      folderId = requireUuid(body.folderId);
    }
    const note = await createNote(userIdOf(res), { folderId });
    res.status(201).json(note);
  })
);

notesRouter.get(
  '/notes/:id',
  asyncHandler(async (req, res) => {
    const note = await getNote(userIdOf(res), requireUuid(req.params.id));
    if (!note) {
      throw notFound();
    }
    res.json(note);
  })
);

notesRouter.patch(
  '/notes/:id',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const noteId = requireUuid(req.params.id);
    const body = bodyRecord(req.body);

    const changes: { title?: string; body?: string } = {};
    if (body.title !== undefined) {
      if (typeof body.title !== 'string' || body.title.length > 500) {
        throw badRequest('The title must be text of at most 500 characters.');
      }
      changes.title = body.title;
    }
    if (body.body !== undefined) {
      if (typeof body.body !== 'string') {
        throw badRequest('The body must be text.');
      }
      changes.body = body.body;
    }
    let folderId: string | null | undefined;
    if (body.folderId !== undefined) {
      folderId = body.folderId === null ? null : requireUuid(body.folderId);
    }
    if (body.pinned !== undefined && typeof body.pinned !== 'boolean') {
      throw badRequest('Pinned must be true or false.');
    }

    if (!(await getNote(userId, noteId))) {
      throw notFound();
    }
    if (folderId !== undefined && !(await setFolder(userId, noteId, folderId))) {
      throw notFound();
    }
    if (typeof body.pinned === 'boolean' && !(await setPinned(userId, noteId, body.pinned))) {
      throw notFound();
    }
    if ((changes.title !== undefined || changes.body !== undefined) && !(await updateNote(userId, noteId, changes))) {
      throw notFound();
    }

    const note = await getNote(userId, noteId);
    if (!note) {
      throw notFound();
    }
    res.json(note);
  })
);

notesRouter.post(
  '/notes/:id/archive',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const noteId = requireUuid(req.params.id);
    if (!(await archive(userId, noteId))) {
      throw notFound();
    }
    const note = await getNote(userId, noteId);
    if (!note) {
      throw notFound();
    }
    res.json(note);
  })
);

notesRouter.post(
  '/notes/:id/unarchive',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const noteId = requireUuid(req.params.id);
    if (!(await unarchive(userId, noteId))) {
      throw notFound();
    }
    const note = await getNote(userId, noteId);
    if (!note) {
      throw notFound();
    }
    res.json(note);
  })
);

notesRouter.post(
  '/notes/:id/trash',
  asyncHandler(async (req, res) => {
    if (!(await trash(userIdOf(res), requireUuid(req.params.id)))) {
      throw notFound();
    }
    res.json({ ok: true });
  })
);

notesRouter.put(
  '/notes/:id/tags',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const noteId = requireUuid(req.params.id);
    const body = bodyRecord(req.body);
    if (!Array.isArray(body.tagIds) || body.tagIds.length > 100) {
      throw badRequest('tagIds must be a list of tag ids.');
    }
    const tagIds = body.tagIds.map((value: unknown) => requireUuid(value));
    if (!(await setNoteTags(userId, noteId, tagIds))) {
      throw notFound();
    }
    const note = await getNote(userId, noteId);
    if (!note) {
      throw notFound();
    }
    res.json(note);
  })
);
"},{"path":"backend/src/features/folders/routes.ts","action":"add","content":"import { Router } from 'express';
import type { PoolClient } from 'pg';
import { query, withTransaction } from '../../lib/db.js';
import { asyncHandler, badRequest, notFound, requireUuid } from '../../lib/errors.js';
import { userIdOf } from '../../lib/requireAuth.js';
import { bodyRecord, queryString } from '../notes/repository.js';

// Paths are relative to /api.
export const foldersRouter = Router();

interface FolderRow {
  id: string;
  parent_id: string | null;
  name: string;
  position: number;
  note_count: number;
}

const FOLDER_SELECT = `
  SELECT f.id, f.parent_id, f.name, f.position,
         (SELECT count(*)::int FROM notes n
           WHERE n.folder_id = f.id AND n.user_id = f.user_id AND n.trashed_at IS NULL) AS note_count
    FROM folders f`;

function mapFolder(row: FolderRow) {
  return {
    id: row.id,
    parentId: row.parent_id,
    name: row.name,
    position: row.position,
    noteCount: row.note_count,
  };
}

function cleanName(value: unknown): string {
  if (typeof value !== 'string') {
    throw badRequest('Enter a folder name.');
  }
  const name = value.trim();
  if (name === '' || name.length > 100) {
    throw badRequest('A folder name must be 1 to 100 characters.');
  }
  return name;
}

async function assertOwnedFolder(client: PoolClient, userId: string, folderId: string): Promise<void> {
  const result = await client.query('SELECT 1 FROM folders WHERE id = $1 AND user_id = $2', [folderId, userId]);
  if (result.rowCount === 0) {
    throw notFound();
  }
}

// The folder itself plus all of its descendants.
async function subtreeIds(client: PoolClient, userId: string, folderId: string): Promise<string[]> {
  const result = await client.query<{ id: string }>(
    `WITH RECURSIVE subtree AS (
       SELECT id FROM folders WHERE id = $1 AND user_id = $2
       UNION
       SELECT f.id FROM folders f JOIN subtree s ON f.parent_id = s.id WHERE f.user_id = $2
     )
     SELECT id FROM subtree`,
    [folderId, userId]
  );
  return result.rows.map((row) => row.id);
}

async function writePositions(client: PoolClient, userId: string, ids: string[]): Promise<void> {
  if (ids.length === 0) {
    return;
  }
  await client.query(
    `UPDATE folders f SET position = v.pos
       FROM unnest($1::uuid[], $2::int[]) AS v(id, pos)
      WHERE f.id = v.id AND f.user_id = $3`,
    [ids, ids.map((_id, index) => index), userId]
  );
}

async function siblingIds(
  client: PoolClient,
  userId: string,
  parentId: string | null,
  excludeId: string | null
): Promise<string[]> {
  const result = await client.query<{ id: string }>(
    `SELECT id FROM folders
      WHERE user_id = $1 AND parent_id IS NOT DISTINCT FROM $2::uuid AND ($3::uuid IS NULL OR id <> $3::uuid)
      ORDER BY position, created_at, id`,
    [userId, parentId, excludeId]
  );
  return result.rows.map((row) => row.id);
}

async function renumberSiblings(client: PoolClient, userId: string, parentId: string | null): Promise<void> {
  await writePositions(client, userId, await siblingIds(client, userId, parentId, null));
}

async function loadFolder(userId: string, folderId: string): Promise<FolderRow> {
  const result = await query<FolderRow>(`${FOLDER_SELECT} WHERE f.id = $1 AND f.user_id = $2`, [folderId, userId]);
  const row = result.rows[0];
  if (!row) {
    throw notFound();
  }
  return row;
}

foldersRouter.get(
  '/folders',
  asyncHandler(async (_req, res) => {
    const result = await query<FolderRow>(
      `${FOLDER_SELECT} WHERE f.user_id = $1 ORDER BY f.position, f.created_at, f.id`,
      [userIdOf(res)]
    );
    res.json({ folders: result.rows.map(mapFolder) });
  })
);

foldersRouter.post(
  '/folders',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const body = bodyRecord(req.body);
    const name = cleanName(body.name);
    const parentId =
      body.parentId === undefined || body.parentId === null ? null : requireUuid(body.parentId);

    const id = await withTransaction(async (client) => {
      if (parentId) {
        await assertOwnedFolder(client, userId, parentId);
      }
      const inserted = await client.query<{ id: string }>(
        `INSERT INTO folders (user_id, parent_id, name, position)
         SELECT $1, $2::uuid, $3,
                COALESCE((SELECT max(position) + 1 FROM folders
                           WHERE user_id = $1 AND parent_id IS NOT DISTINCT FROM $2::uuid), 0)
         RETURNING id`,
        [userId, parentId, name]
      );
      return inserted.rows[0].id;
    });
    res.status(201).json(mapFolder(await loadFolder(userId, id)));
  })
);

foldersRouter.patch(
  '/folders/:id',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const folderId = requireUuid(req.params.id);
    const body = bodyRecord(req.body);

    const name = body.name === undefined ? undefined : cleanName(body.name);
    let requestedParent: string | null | undefined;
    if (body.parentId !== undefined) {
      requestedParent = body.parentId === null ? null : requireUuid(body.parentId);
    }
    let position: number | undefined;
    if (body.position !== undefined) {
      if (typeof body.position !== 'number' || !Number.isInteger(body.position) || body.position < 0) {
        throw badRequest('The position must be a non-negative whole number.');
      }
      position = body.position;
    }

    await withTransaction(async (client) => {
      const current = await client.query<{ parent_id: string | null }>(
        'SELECT parent_id FROM folders WHERE id = $1 AND user_id = $2 FOR UPDATE',
        [folderId, userId]
      );
      if (current.rowCount === 0) {
        throw notFound();
      }
      const oldParent = current.rows[0].parent_id;
      const newParent = requestedParent === undefined ? oldParent : requestedParent;
      const parentChanged = newParent !== oldParent;

      if (parentChanged && newParent) {
        await assertOwnedFolder(client, userId, newParent);
        const subtree = await subtreeIds(client, userId, folderId);
        if (subtree.includes(newParent)) {
          throw badRequest('A folder cannot be moved into itself or one of its subfolders.');
        }
      }

      await client.query(
        'UPDATE folders SET name = COALESCE($3, name), parent_id = $4 WHERE id = $1 AND user_id = $2',
        [folderId, userId, name ?? null, newParent]
      );

      if (parentChanged || position !== undefined) {
        const ids = await siblingIds(client, userId, newParent, folderId);
        const at = position === undefined ? ids.length : Math.min(position, ids.length);
        ids.splice(at, 0, folderId);
        await writePositions(client, userId, ids);
        if (parentChanged) {
          await renumberSiblings(client, userId, oldParent);
        }
      }
    });

    res.json(mapFolder(await loadFolder(userId, folderId)));
  })
);

foldersRouter.delete(
  '/folders/:id',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const folderId = requireUuid(req.params.id);
    const mode = queryString(req.query.notes);
    const targetText = queryString(req.query.targetFolderId);
    if (mode !== undefined && mode !== 'move' && mode !== 'uncategorize') {
      throw badRequest('Choose whether to move the notes or leave them uncategorized.');
    }
    const targetId = targetText ? requireUuid(targetText) : null;

    const outcome = await withTransaction(async (client) => {
      const current = await client.query<{ parent_id: string | null }>(
        'SELECT parent_id FROM folders WHERE id = $1 AND user_id = $2 FOR UPDATE',
        [folderId, userId]
      );
      if (current.rowCount === 0) {
        throw notFound();
      }
      const ids = await subtreeIds(client, userId, folderId);
      const counted = await client.query<{ count: number }>(
        `SELECT count(*)::int AS count FROM notes
          WHERE user_id = $1 AND folder_id = ANY($2::uuid[]) AND trashed_at IS NULL`,
        [userId, ids]
      );
      const affected = counted.rows[0].count;

      if (targetId) {
        await assertOwnedFolder(client, userId, targetId);
        if (ids.includes(targetId)) {
          throw badRequest('Choose a folder outside the one being deleted.');
        }
      }
      if (affected > 0) {
        if (mode === undefined) {
          throw badRequest('Choose what to do with the notes in this folder.');
        }
        if (mode === 'move' && !targetId) {
          throw badRequest('Choose a folder to move the notes to.');
        }
        await client.query(
          `UPDATE notes SET folder_id = $3
            WHERE user_id = $1 AND folder_id = ANY($2::uuid[]) AND trashed_at IS NULL`,
          [userId, ids, mode === 'move' ? targetId : null]
        );
      }

      await client.query('DELETE FROM folders WHERE id = $1 AND user_id = $2', [folderId, userId]);
      await renumberSiblings(client, userId, current.rows[0].parent_id);
      return { deletedFolders: ids.length, affectedNotes: affected };
    });

    res.json(outcome);
  })
);
"},{"path":"backend/src/features/tags/routes.ts","action":"add","content":"import { Router } from 'express';
import { query, withTransaction } from '../../lib/db.js';
import { asyncHandler, badRequest, conflict, notFound, requireUuid } from '../../lib/errors.js';
import { userIdOf } from '../../lib/requireAuth.js';
import { bodyRecord } from '../notes/repository.js';

// Paths are relative to /api.
export const tagsRouter = Router();

export const TAG_COLORS = ['gray', 'red', 'orange', 'yellow', 'green', 'blue', 'purple', 'pink'] as const;

interface TagRow {
  id: string;
  name: string;
  color: string;
  note_count: number;
}

const TAG_SELECT = `
  SELECT t.id, t.name, t.color,
         (SELECT count(*)::int FROM note_tags nt
            JOIN notes n ON n.id = nt.note_id AND n.user_id = t.user_id
           WHERE nt.tag_id = t.id AND n.trashed_at IS NULL) AS note_count
    FROM tags t`;

function mapTag(row: TagRow) {
  return { id: row.id, name: row.name, color: row.color, noteCount: row.note_count };
}

function cleanName(value: unknown): string {
  if (typeof value !== 'string') {
    throw badRequest('Enter a tag name.');
  }
  const name = value.trim();
  if (name === '' || name.length > 50) {
    throw badRequest('A tag name must be 1 to 50 characters.');
  }
  return name;
}

function cleanColor(value: unknown): string {
  const match = TAG_COLORS.find((color) => color === value);
  if (!match) {
    throw badRequest('Choose one of the available tag colors.');
  }
  return match;
}

async function assertNameFree(userId: string, name: string, exceptId: string | null): Promise<void> {
  const clash = await query(
    `SELECT 1 FROM tags
      WHERE user_id = $1 AND lower(name) = lower($2) AND ($3::uuid IS NULL OR id <> $3::uuid)`,
    [userId, name, exceptId]
  );
  if ((clash.rowCount ?? 0) > 0) {
    throw conflict(`A tag named ${name} already exists.`, 'tag_exists');
  }
}

async function loadTag(userId: string, tagId: string): Promise<TagRow> {
  const result = await query<TagRow>(`${TAG_SELECT} WHERE t.id = $1 AND t.user_id = $2`, [tagId, userId]);
  const row = result.rows[0];
  if (!row) {
    throw notFound();
  }
  return row;
}

tagsRouter.get(
  '/tags',
  asyncHandler(async (_req, res) => {
    const result = await query<TagRow>(`${TAG_SELECT} WHERE t.user_id = $1 ORDER BY lower(t.name), t.id`, [
      userIdOf(res),
    ]);
    res.json({ tags: result.rows.map(mapTag) });
  })
);

tagsRouter.post(
  '/tags',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const body = bodyRecord(req.body);
    const name = cleanName(body.name);
    const color = body.color === undefined ? 'gray' : cleanColor(body.color);
    await assertNameFree(userId, name, null);
    const inserted = await query<{ id: string }>(
      'INSERT INTO tags (user_id, name, color) VALUES ($1, $2, $3) RETURNING id',
      [userId, name, color]
    );
    res.status(201).json(mapTag(await loadTag(userId, inserted.rows[0].id)));
  })
);

tagsRouter.patch(
  '/tags/:id',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const tagId = requireUuid(req.params.id);
    const body = bodyRecord(req.body);
    const name = body.name === undefined ? null : cleanName(body.name);
    const color = body.color === undefined ? null : cleanColor(body.color);

    await loadTag(userId, tagId);
    if (name !== null) {
      await assertNameFree(userId, name, tagId);
    }
    await query(
      'UPDATE tags SET name = COALESCE($3, name), color = COALESCE($4, color) WHERE id = $1 AND user_id = $2',
      [tagId, userId, name, color]
    );
    res.json(mapTag(await loadTag(userId, tagId)));
  })
);

tagsRouter.delete(
  '/tags/:id',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const tagId = requireUuid(req.params.id);
    await withTransaction(async (client) => {
      const owned = await client.query('SELECT 1 FROM tags WHERE id = $1 AND user_id = $2 FOR UPDATE', [
        tagId,
        userId,
      ]);
      if (owned.rowCount === 0) {
        throw notFound();
      }
      await client.query('DELETE FROM note_tags WHERE tag_id = $1 AND user_id = $2', [tagId, userId]);
      await client.query('DELETE FROM tags WHERE id = $1 AND user_id = $2', [tagId, userId]);
    });
    res.status(204).end();
  })
);
"},{"path":"backend/src/features/search/routes.ts","action":"add","content":"import { Router } from 'express';
import { query } from '../../lib/db.js';
import { asyncHandler, badRequest, requireUuid } from '../../lib/errors.js';
import { userIdOf } from '../../lib/requireAuth.js';
import { FOLDER_JOIN, SUMMARY_COLUMNS, mapSummary, parseDateParam, queryString } from '../notes/repository.js';
import type { SummaryRow } from '../notes/repository.js';

// Paths are relative to /api.
export const searchRouter = Router();

const RESULT_LIMIT = 50;
const MAX_QUERY_LENGTH = 500;

// U+0002 and U+0003 wrap each match so the client can build highlight elements itself.
const HEADLINE_OPTIONS = 'StartSel=\u0002, StopSel=\u0003, MaxFragments=2, MaxWords=30, MinWords=12, ShortWord=2';

searchRouter.get(
  '/search',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const text = (queryString(req.query.q) ?? '').trim().slice(0, MAX_QUERY_LENGTH);
    const folderId = queryString(req.query.folderId);
    const tagId = queryString(req.query.tagId);
    const from = queryString(req.query.from);
    const to = queryString(req.query.to);
    const dateField = queryString(req.query.dateField);
    const archived = queryString(req.query.archived);
    const hasAttachments = queryString(req.query.hasAttachments);

    if (dateField !== undefined && dateField !== '' && dateField !== 'updated' && dateField !== 'created') {
      throw badRequest('Invalid query parameter.');
    }
    if (archived !== undefined && archived !== '' && archived !== 'only') {
      throw badRequest('Invalid query parameter.');
    }
    const folder = folderId ? requireUuid(folderId) : null;
    const tag = tagId ? requireUuid(tagId) : null;
    const fromDate = from ? parseDateParam(from) : null;
    const toDate = to ? parseDateParam(to) : null;

    if (text === '') {
      res.json({ results: [] });
      return;
    }

    const params: unknown[] = [userId, text, HEADLINE_OPTIONS];
    const add = (value: unknown): string => {
      params.push(value);
      return `$${params.length}`;
    };

    const where = [
      'n.user_id = $1',
      'n.trashed_at IS NULL',
      archived === 'only' ? 'n.is_archived = true' : 'n.is_archived = false',
      'numnode(q.tsq) > 0',
      'n.search_vector @@ q.tsq',
    ];
    if (folder) {
      where.push(`n.folder_id = ${add(folder)}`);
    }
    if (tag) {
      where.push(
        `EXISTS (SELECT 1 FROM note_tags nt WHERE nt.note_id = n.id AND nt.user_id = n.user_id AND nt.tag_id = ${add(
          tag
        )})`
      );
    }
    const dateColumn = dateField === 'created' ? 'n.created_at' : 'n.updated_at';
    if (fromDate) {
      where.push(`${dateColumn} >= ${add(fromDate)}::date`);
    }
    if (toDate) {
      where.push(`${dateColumn} < (${add(toDate)}::date + 1)`);
    }
    if (hasAttachments === 'true') {
      where.push('EXISTS (SELECT 1 FROM attachments a WHERE a.note_id = n.id AND a.user_id = n.user_id)');
    }

    // OD-007: ts_rank descending, then most recently updated. Snippets are built only for
    // the limited hit set, and only when the body text itself matches.
    const result = await query<SummaryRow & { snippet: string | null }>(
      `WITH q AS (
         SELECT websearch_to_tsquery('english', $2::text) || websearch_to_tsquery('simple', $2::text) AS tsq
       ),
       hits AS (
         SELECT n.id, ts_rank(n.search_vector, q.tsq) AS score
           FROM notes n CROSS JOIN q
          WHERE ${where.join(' AND ')}
          ORDER BY score DESC, n.updated_at DESC, n.id
          LIMIT ${RESULT_LIMIT}
       )
       SELECT ${SUMMARY_COLUMNS},
              CASE
                WHEN n.body_text <> '' AND to_tsvector('english', n.body_text) @@ q.tsq
                  THEN ts_headline('english', n.body_text, q.tsq, $3::text)
                WHEN n.body_text <> '' AND to_tsvector('simple', n.body_text) @@ q.tsq
                  THEN ts_headline('simple', n.body_text, q.tsq, $3::text)
                ELSE NULL
              END AS snippet
         FROM hits h
         JOIN notes n ON n.id = h.id
         CROSS JOIN q
         ${FOLDER_JOIN}
        ORDER BY h.score DESC, n.updated_at DESC, n.id`,
      params
    );

    res.json({
      results: result.rows.map((row) => ({ ...mapSummary(row), snippet: row.snippet })),
    });
  })
);
"},{"path":"backend/src/features/trash/purge.ts","action":"add","content":"import { query } from '../../lib/db.js';
import { deleteFile } from '../../lib/storage.js';

const DEFAULT_RETENTION_DAYS = 30;
const DEFAULT_INTERVAL_MINUTES = 60;

function envPositive(name: string, fallback: number): number {
  const value = Number(process.env[name]);
  return Number.isFinite(value) && value > 0 ? value : fallback;
}

export function trashRetentionSeconds(): number {
  return envPositive('TRASH_RETENTION_DAYS', DEFAULT_RETENTION_DAYS) * 24 * 60 * 60;
}

// SQL condition that is true while a trashed note is still inside the retention window.
// The parameter at paramIndex must be bound to trashRetentionSeconds().
export function withinRetentionSql(column: string, paramIndex: number): string {
  return `${column} > now() - make_interval(secs => $${paramIndex})`;
}

export async function purgeExpiredTrash(): Promise<number> {
  const seconds = trashRetentionSeconds();
  const expired = await query<{ id: string }>(
    `SELECT id FROM notes
      WHERE trashed_at IS NOT NULL AND NOT (${withinRetentionSql('trashed_at', 1)})`,
    [seconds]
  );
  if (expired.rows.length === 0) {
    return 0;
  }
  const ids = expired.rows.map((row) => row.id);

  const files = await query<{ storage_key: string }>(
    'SELECT storage_key FROM attachments WHERE note_id = ANY($1::uuid[])',
    [ids]
  );
  for (const file of files.rows) {
    try {
      await deleteFile(file.storage_key);
    } catch (err) {
      console.error('Could not delete an attachment file during trash purge:', err);
    }
  }

  const deleted = await query(
    `DELETE FROM notes
      WHERE id = ANY($1::uuid[]) AND trashed_at IS NOT NULL AND NOT (${withinRetentionSql('trashed_at', 2)})`,
    [ids, seconds]
  );
  return deleted.rowCount ?? 0;
}

export function startTrashPurge(): NodeJS.Timeout {
  let running = false;
  const run = async (): Promise<void> => {
    if (running) {
      return;
    }
    running = true;
    try {
      const count = await purgeExpiredTrash();
      if (count > 0) {
        console.log(`Purged ${count} expired trashed note(s).`);
      }
    } catch (err) {
      console.error('Trash purge failed:', err);
    } finally {
      running = false;
    }
  };

  void run();
  const intervalMs = envPositive('TRASH_PURGE_INTERVAL_MINUTES', DEFAULT_INTERVAL_MINUTES) * 60 * 1000;
  const timer = setInterval(() => {
    void run();
  }, intervalMs);
  timer.unref();
  return timer;
}
"},{"path":"backend/src/features/trash/routes.ts","action":"add","content":"import { Router } from 'express';
import { query, withTransaction } from '../../lib/db.js';
import { asyncHandler, notFound, requireUuid } from '../../lib/errors.js';
import { userIdOf } from '../../lib/requireAuth.js';
import { deleteFile } from '../../lib/storage.js';
import { recordActivity } from '../activity/repository.js';
import { FOLDER_JOIN, SUMMARY_COLUMNS, getNote, mapSummary } from '../notes/repository.js';
import type { SummaryRow } from '../notes/repository.js';
import { trashRetentionSeconds, withinRetentionSql } from './purge.js';

// Paths are relative to /api.
export const trashRouter = Router();

const GONE_MESSAGE = 'This note is no longer in the trash.';

trashRouter.get(
  '/trash',
  asyncHandler(async (_req, res) => {
    const result = await query<SummaryRow & { trashed_at: Date; expires_at: Date }>(
      `SELECT ${SUMMARY_COLUMNS},
              n.trashed_at,
              n.trashed_at + make_interval(secs => $2) AS expires_at
         FROM notes n
         ${FOLDER_JOIN}
        WHERE n.user_id = $1 AND n.trashed_at IS NOT NULL AND ${withinRetentionSql('n.trashed_at', 2)}
        ORDER BY n.trashed_at DESC, n.id`,
      [userIdOf(res), trashRetentionSeconds()]
    );
    res.json({
      notes: result.rows.map((row) => ({
        ...mapSummary(row),
        trashedAt: row.trashed_at,
        expiresAt: row.expires_at,
      })),
    });
  })
);

trashRouter.post(
  '/trash/:id/restore',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const noteId = requireUuid(req.params.id);

    const folderName = await withTransaction(async (client) => {
      const found = await client.query<{ folder_id: string | null }>(
        `SELECT folder_id FROM notes
          WHERE id = $1 AND user_id = $2 AND trashed_at IS NOT NULL AND ${withinRetentionSql('trashed_at', 3)}
          FOR UPDATE`,
        [noteId, userId, trashRetentionSeconds()]
      );
      const row = found.rows[0];
      if (!row) {
        throw notFound(GONE_MESSAGE);
      }

      let folderId: string | null = null;
      let name: string | null = null;
      if (row.folder_id) {
        const folder = await client.query<{ id: string; name: string }>(
          'SELECT id, name FROM folders WHERE id = $1 AND user_id = $2',
          [row.folder_id, userId]
        );
        if (folder.rows[0]) {
          folderId = folder.rows[0].id;
          name = folder.rows[0].name;
        }
      }

      await client.query(
        `UPDATE notes SET trashed_at = NULL, restored_at = now(), folder_id = $3
          WHERE id = $1 AND user_id = $2`,
        [noteId, userId, folderId]
      );
      await recordActivity(client, { userId, noteId, event: 'restored' });
      return name;
    });

    const note = await getNote(userId, noteId);
    if (!note) {
      throw notFound(GONE_MESSAGE);
    }
    res.json({
      note,
      restoredTo: folderName === null ? 'uncategorized' : 'folder',
      folderName,
    });
  })
);

trashRouter.delete(
  '/trash/:id',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const noteId = requireUuid(req.params.id);

    const found = await query(
      'SELECT 1 FROM notes WHERE id = $1 AND user_id = $2 AND trashed_at IS NOT NULL',
      [noteId, userId]
    );
    if (found.rowCount === 0) {
      throw notFound();
    }

    const files = await query<{ storage_key: string }>(
      'SELECT storage_key FROM attachments WHERE note_id = $1 AND user_id = $2',
      [noteId, userId]
    );
    for (const file of files.rows) {
      await deleteFile(file.storage_key);
    }

    // Cascades remove checklist items, versions, attachments, tag links and activity.
    await query('DELETE FROM notes WHERE id = $1 AND user_id = $2 AND trashed_at IS NOT NULL', [noteId, userId]);
    res.status(204).end();
  })
);
"},{"path":"backend/src/features/checklists/routes.ts","action":"add","content":"import { Router } from 'express';
import { query, withTransaction } from '../../lib/db.js';
import { asyncHandler, badRequest, notFound, requireUuid } from '../../lib/errors.js';
import { userIdOf } from '../../lib/requireAuth.js';
import { setChecklistItemChecked } from '../export/markdown.js';
import { bodyRecord } from '../notes/repository.js';

// Paths are relative to /api.
export const checklistsRouter = Router();

interface ItemRow {
  id: string;
  note_id: string;
  text: string;
  checked: boolean;
  position: number;
}

function mapItem(row: ItemRow) {
  return {
    id: row.id,
    noteId: row.note_id,
    text: row.text,
    checked: row.checked,
    position: row.position,
  };
}

const ITEM_SELECT = `
  SELECT c.id, c.note_id, c.text, c.checked, c.position
    FROM checklist_items c
    JOIN notes n ON n.id = c.note_id AND n.user_id = c.user_id`;

checklistsRouter.get(
  '/notes/:noteId/checklist-items',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const noteId = requireUuid(req.params.noteId);
    const note = await query('SELECT 1 FROM notes WHERE id = $1 AND user_id = $2 AND trashed_at IS NULL', [
      noteId,
      userId,
    ]);
    if (note.rowCount === 0) {
      throw notFound();
    }
    const result = await query<ItemRow>(
      `${ITEM_SELECT}
        WHERE c.note_id = $1 AND c.user_id = $2 AND n.trashed_at IS NULL
        ORDER BY c.position`,
      [noteId, userId]
    );
    const items = result.rows.map(mapItem);
    res.json({
      items,
      summary: { done: items.filter((item) => item.checked).length, total: items.length },
    });
  })
);

checklistsRouter.get(
  '/checklist-items/:id',
  asyncHandler(async (req, res) => {
    const result = await query<ItemRow>(
      `${ITEM_SELECT} WHERE c.id = $1 AND c.user_id = $2 AND n.trashed_at IS NULL`,
      [requireUuid(req.params.id), userIdOf(res)]
    );
    const row = result.rows[0];
    if (!row) {
      throw notFound();
    }
    res.json(mapItem(row));
  })
);

checklistsRouter.patch(
  '/checklist-items/:id',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const itemId = requireUuid(req.params.id);
    const body = bodyRecord(req.body);
    if (typeof body.checked !== 'boolean') {
      throw badRequest('Checked must be true or false.');
    }
    const checked = body.checked;

    const updated = await withTransaction(async (client) => {
      // Locking the note row serializes this body rewrite with concurrent saves.
      const found = await client.query<{ note_id: string; position: number; body: string }>(
        `SELECT c.note_id, c.position, n.body
           FROM checklist_items c
           JOIN notes n ON n.id = c.note_id AND n.user_id = c.user_id
          WHERE c.id = $1 AND c.user_id = $2 AND n.trashed_at IS NULL
          FOR UPDATE OF n`,
        [itemId, userId]
      );
      const row = found.rows[0];
      if (!row) {
        throw notFound();
      }

      const item = await client.query<ItemRow>(
        `UPDATE checklist_items SET checked = $3
          WHERE id = $1 AND user_id = $2
          RETURNING id, note_id, text, checked, position`,
        [itemId, userId, checked]
      );
      await client.query(
        'UPDATE notes SET body = $3, updated_at = now() WHERE id = $1 AND user_id = $2',
        [row.note_id, userId, setChecklistItemChecked(row.body, row.position, checked)]
      );
      return item.rows[0];
    });

    res.json(mapItem(updated));
  })
);
"},{"path":"backend/src/features/attachments/routes.ts","action":"add","content":"import * as path from 'node:path';
import { Router } from 'express';
import type { NextFunction, Request, Response } from 'express';
import multer from 'multer';
import { query } from '../../lib/db.js';
import {
  AppError,
  asyncHandler,
  badRequest,
  notFound,
  payloadTooLarge,
  requireUuid,
  unsupportedMediaType,
} from '../../lib/errors.js';
import { userIdOf } from '../../lib/requireAuth.js';
import { createReadStream, deleteFile, saveBuffer } from '../../lib/storage.js';

// Paths are relative to /api. Attachment files are only ever served through the
// authenticated content route; UPLOAD_DIR is never mounted as a static directory.
export const attachmentsRouter = Router();

const DEFAULT_MAX_BYTES = 10485760;

// OD-002: accepted extensions and the MIME type served for each.
export const ATTACHMENT_MIME_TYPES: Record<string, string> = {
  png: 'image/png',
  jpg: 'image/jpeg',
  jpeg: 'image/jpeg',
  gif: 'image/gif',
  webp: 'image/webp',
  pdf: 'application/pdf',
  txt: 'text/plain',
  md: 'text/markdown',
  csv: 'text/csv',
  doc: 'application/msword',
  docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  xls: 'application/vnd.ms-excel',
  xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  ppt: 'application/vnd.ms-powerpoint',
  pptx: 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
  odt: 'application/vnd.oasis.opendocument.text',
  ods: 'application/vnd.oasis.opendocument.spreadsheet',
  odp: 'application/vnd.oasis.opendocument.presentation',
  rtf: 'application/rtf',
};

export function attachmentMaxBytes(): number {
  const value = Number(process.env.ATTACHMENT_MAX_BYTES);
  return Number.isFinite(value) && value > 0 ? Math.floor(value) : DEFAULT_MAX_BYTES;
}

// Returns the MIME type mapped to the file name's extension, or null when not accepted.
export function attachmentMimeType(fileName: string): string | null {
  const extension = path.extname(fileName).slice(1).toLowerCase();
  return Object.prototype.hasOwnProperty.call(ATTACHMENT_MIME_TYPES, extension)
    ? ATTACHMENT_MIME_TYPES[extension]
    : null;
}

function tooLargeMessage(): string {
  const megabytes = Number((attachmentMaxBytes() / (1024 * 1024)).toFixed(1));
  return `File is too large. The maximum size is ${megabytes} MB.`;
}

const UNSUPPORTED_MESSAGE =
  'Unsupported file type. Accepted: images, PDF, text and common document formats.';

// Busboy hands over file names as latin1; recover UTF-8 names when that is what was sent.
function decodeFileName(raw: string): string {
  let name = raw;
  if (/[^\u0000-\u007f]/.test(raw)) {
    const recovered = Buffer.from(raw, 'latin1').toString('utf8');
    if (!recovered.includes('\ufffd')) {
      name = recovered;
    }
  }
  // eslint-disable-next-line no-control-regex
  name = path.basename(name.replace(/\\/g, '/')).replace(/[\u0000-\u001f\u007f]/g, '').trim();
  return name === '' ? 'file' : name.slice(0, 255);
}

function fileFilter(_req: Request, file: Express.Multer.File, cb: multer.FileFilterCallback): void {
  const mapped = attachmentMimeType(decodeFileName(file.originalname));
  const reported = file.mimetype.toLowerCase();
  const accepted =
    mapped !== null && (reported === '' || reported === 'application/octet-stream' || reported === mapped);
  if (!accepted) {
    cb(unsupportedMediaType(UNSUPPORTED_MESSAGE, 'unsupported_file_type'));
    return;
  }
  cb(null, true);
}

function uploadSingle(req: Request, res: Response, next: NextFunction): void {
  const handler = multer({
    storage: multer.memoryStorage(),
    limits: { fileSize: attachmentMaxBytes() },
    fileFilter,
  }).single('file');

  handler(req, res, (err: unknown) => {
    if (err instanceof AppError) {
      next(err);
      return;
    }
    if (err instanceof multer.MulterError) {
      if (err.code === 'LIMIT_FILE_SIZE') {
        next(payloadTooLarge(tooLargeMessage(), 'file_too_large'));
      } else {
        next(badRequest('The upload could not be processed.'));
      }
      return;
    }
    if (err) {
      next(err);
      return;
    }
    if (!req.file) {
      next(badRequest('Choose a file to upload.', 'no_file'));
      return;
    }
    next();
  });
}

interface AttachmentRow {
  id: string;
  note_id: string;
  file_name: string;
  mime_type: string;
  size_bytes: string;
  created_at: Date;
}

function mapAttachment(row: AttachmentRow) {
  return {
    id: row.id,
    noteId: row.note_id,
    fileName: row.file_name,
    mimeType: row.mime_type,
    sizeBytes: Number(row.size_bytes),
    createdAt: row.created_at,
  };
}

async function assertOwnedActiveNote(userId: string, noteId: string): Promise<void> {
  const result = await query('SELECT 1 FROM notes WHERE id = $1 AND user_id = $2 AND trashed_at IS NULL', [
    noteId,
    userId,
  ]);
  if (result.rowCount === 0) {
    throw notFound();
  }
}

function encodeFileName(name: string): string {
  return encodeURIComponent(name).replace(
    /['()*]/g,
    (ch) => `%${ch.charCodeAt(0).toString(16).toUpperCase()}`
  );
}

attachmentsRouter.post(
  '/notes/:noteId/attachments',
  asyncHandler(async (req, _res, next) => {
    await assertOwnedActiveNote(userIdOf(_res), requireUuid(req.params.noteId));
    next();
  }),
  uploadSingle,
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const noteId = requireUuid(req.params.noteId);
    const file = req.file;
    if (!file) {
      throw badRequest('Choose a file to upload.', 'no_file');
    }
    const fileName = decodeFileName(file.originalname);
    const mimeType = attachmentMimeType(fileName);
    if (!mimeType) {
      throw unsupportedMediaType(UNSUPPORTED_MESSAGE, 'unsupported_file_type');
    }

    const storageKey = await saveBuffer(file.buffer, 'attachments');
    try {
      const inserted = await query<AttachmentRow>(
        `INSERT INTO attachments (note_id, user_id, file_name, mime_type, size_bytes, storage_key)
         VALUES ($1, $2, $3, $4, $5, $6)
         RETURNING id, note_id, file_name, mime_type, size_bytes, created_at`,
        [noteId, userId, fileName, mimeType, file.size, storageKey]
      );
      res.status(201).json(mapAttachment(inserted.rows[0]));
    } catch (err) {
      await deleteFile(storageKey);
      throw err;
    }
  })
);

attachmentsRouter.get(
  '/notes/:noteId/attachments',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const noteId = requireUuid(req.params.noteId);
    await assertOwnedActiveNote(userId, noteId);
    const result = await query<AttachmentRow>(
      `SELECT id, note_id, file_name, mime_type, size_bytes, created_at
         FROM attachments
        WHERE note_id = $1 AND user_id = $2
        ORDER BY created_at, id`,
      [noteId, userId]
    );
    res.json({ attachments: result.rows.map(mapAttachment) });
  })
);

attachmentsRouter.get(
  '/attachments/:id/content',
  asyncHandler(async (req, res, next) => {
    const result = await query<{ file_name: string; storage_key: string; size_bytes: string }>(
      'SELECT file_name, storage_key, size_bytes FROM attachments WHERE id = $1 AND user_id = $2',
      [requireUuid(req.params.id), userIdOf(res)]
    );
    const row = result.rows[0];
    if (!row) {
      throw notFound();
    }

    const mimeType = attachmentMimeType(row.file_name) ?? 'application/octet-stream';
    const inline = mimeType.startsWith('image/') || mimeType === 'application/pdf';
    const stream = createReadStream(row.storage_key);

    stream.on('error', (err: NodeJS.ErrnoException) => {
      if (res.headersSent) {
        res.destroy();
      } else if (err.code === 'ENOENT') {
        next(notFound());
      } else {
        next(err);
      }
    });
    stream.once('open', () => {
      if (inline) {
        res.setHeader('Content-Disposition', `inline; filename*=UTF-8''${encodeFileName(row.file_name)}`);
      } else {
        res.attachment(row.file_name);
      }
      res.setHeader('Content-Type', mimeType);
      res.setHeader('X-Content-Type-Options', 'nosniff');
      res.setHeader('Content-Length', String(Number(row.size_bytes)));
      stream.pipe(res);
    });
  })
);

attachmentsRouter.delete(
  '/attachments/:id',
  asyncHandler(async (req, res) => {
    const deleted = await query<{ storage_key: string }>(
      'DELETE FROM attachments WHERE id = $1 AND user_id = $2 RETURNING storage_key',
      [requireUuid(req.params.id), userIdOf(res)]
    );
    const row = deleted.rows[0];
    if (!row) {
      throw notFound();
    }
    try {
      await deleteFile(row.storage_key);
    } catch (err) {
      console.error('Could not delete an attachment file:', err);
    }
    res.status(204).end();
  })
);
"},{"path":"backend/src/features/versions/routes.ts","action":"add","content":"import { Router } from 'express';
import { query, withTransaction } from '../../lib/db.js';
import { asyncHandler, notFound, requireUuid } from '../../lib/errors.js';
import { userIdOf } from '../../lib/requireAuth.js';
import { recordActivity } from '../activity/repository.js';
import { htmlToPlainText } from '../export/markdown.js';
import { getNote, syncChecklistItems } from '../notes/repository.js';

// Paths are relative to /api.
export const versionsRouter = Router();

const PREVIEW_LENGTH = 140;

// OD-020: an excerpt of the body text, falling back to the title, then "Untitled note".
function versionPreview(title: string, bodyText: string): string {
  const body = bodyText.replace(/\s+/g, ' ').trim();
  if (body !== '') {
    return body.slice(0, PREVIEW_LENGTH);
  }
  const heading = title.replace(/\s+/g, ' ').trim();
  return heading !== '' ? heading.slice(0, PREVIEW_LENGTH) : 'Untitled note';
}

versionsRouter.get(
  '/notes/:noteId/versions',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const noteId = requireUuid(req.params.noteId);
    const note = await query('SELECT 1 FROM notes WHERE id = $1 AND user_id = $2 AND trashed_at IS NULL', [
      noteId,
      userId,
    ]);
    if (note.rowCount === 0) {
      throw notFound();
    }
    const result = await query<{
      id: string;
      created_at: Date;
      reason: string;
      title: string;
      excerpt: string;
    }>(
      `SELECT id, created_at, reason, title, left(body_text, 600) AS excerpt
         FROM note_versions
        WHERE note_id = $1 AND user_id = $2
        ORDER BY created_at DESC, id DESC`,
      [noteId, userId]
    );
    res.json({
      versions: result.rows.map((row) => ({
        id: row.id,
        createdAt: row.created_at,
        reason: row.reason,
        preview: versionPreview(row.title, row.excerpt),
      })),
    });
  })
);

versionsRouter.get(
  '/versions/:id',
  asyncHandler(async (req, res) => {
    const result = await query<{
      id: string;
      note_id: string;
      title: string;
      body: string;
      body_text: string;
      reason: string;
      created_at: Date;
    }>(
      `SELECT id, note_id, title, body, body_text, reason, created_at
         FROM note_versions
        WHERE id = $1 AND user_id = $2`,
      [requireUuid(req.params.id), userIdOf(res)]
    );
    const row = result.rows[0];
    if (!row) {
      throw notFound();
    }
    res.json({
      id: row.id,
      noteId: row.note_id,
      title: row.title,
      body: row.body,
      bodyText: row.body_text,
      reason: row.reason,
      createdAt: row.created_at,
      preview: versionPreview(row.title, row.body_text),
    });
  })
);

versionsRouter.post(
  '/versions/:id/restore',
  asyncHandler(async (req, res) => {
    const userId = userIdOf(res);
    const versionId = requireUuid(req.params.id);

    const noteId = await withTransaction(async (client) => {
      const found = await client.query<{
        note_id: string;
        title: string;
        body: string;
        cur_title: string;
        cur_body: string;
        cur_body_text: string;
      }>(
        `SELECT v.note_id, v.title, v.body,
                n.title AS cur_title, n.body AS cur_body, n.body_text AS cur_body_text
           FROM note_versions v
           JOIN notes n ON n.id = v.note_id AND n.user_id = v.user_id
          WHERE v.id = $1 AND v.user_id = $2 AND n.trashed_at IS NULL
          FOR UPDATE OF n`,
        [versionId, userId]
      );
      const row = found.rows[0];
      if (!row) {
        throw notFound();
      }

      // Keep the state being replaced; restoring never prunes existing versions.
      await client.query(
        `INSERT INTO note_versions (note_id, user_id, title, body, body_text, reason)
         VALUES ($1, $2, $3, $4, $5, 'restore')`,
        [row.note_id, userId, row.cur_title, row.cur_body, row.cur_body_text]
      );
      await client.query(
        `UPDATE notes
            SET title = $3, body = $4, body_text = $5, updated_at = now()
          WHERE id = $1 AND user_id = $2`,
        [row.note_id, userId, row.title, row.body, htmlToPlainText(row.body)]
      );
      await syncChecklistItems(client, userId, row.note_id, row.body);
      await recordActivity(client, { userId, noteId: row.note_id, event: 'version_restored' });
      return row.note_id;
    });

    const note = await getNote(userId, noteId);
    if (!note) {
      throw notFound();
    }
    res.json(note);
  })
);
"}]}]}

